package main

import (
	_ "embed"
	"fmt"
	"sort"
	"strings"
)

//go:embed spotchecks.md
var spotChecks string

// docsReadme is docs/coverage/README.md: the method, written once, with the
// pins, tier counts and error figures filled in from the run.
func docsReadme(m *model, r *results) []byte {
	var b strings.Builder
	w := func(format string, a ...any) { fmt.Fprintf(&b, format, a...) }
	t := r.total
	src := m.src

	w("# Coverage of AWS: ACK and ack-extensions\n\n")
	w("<!-- Generated by hack/coverage/run.sh; do not edit. The spot-check section comes from hack/coverage/spotchecks.md. -->\n\n")
	w("This directory measures how much of AWS is covered by Kubernetes kinds: by the controllers ACK releases (**official**), and by the kinds in this repository (**ours**) beyond them. The root [README](../../README.md) shows the summary; the data is here.\n\n")
	w("![Total](bars/_total.svg)\n\n")
	w("| | Resources | Attributes |\n| --- | ---: | ---: |\n")
	w("| In the CloudFormation schemas (the denominator) | %s | %s |\n", commas(t.resTotal), commas(t.attrTotal))
	w("| Covered by an official ACK kind | %s | %s (%s%%) |\n", commas(t.resOfficial), commas(t.attrOfficial), pct1(t.attrOfficial, t.attrTotal))
	w("| Covered by ours, beyond official | %s | %s (%s%%) |\n", commas(t.resOursBeyond), commas(t.attrOursBeyond), pct1(t.attrOursBeyond, t.attrTotal))
	w("| Covered by neither | %s | %s (%s%%) |\n", commas(t.resTotal-t.resOfficial-t.resOursBeyond), commas(t.attrUncov), pct1(t.attrUncov, t.attrTotal))
	w("| Matched by the Terraform `aws` provider (estimate, [below](#terraform)) | | about %s (%s%%), at least %s (%s%%) |\n\n", commas(r.tfTotal.l2), pct1(r.tfTotal.l2, r.tfTotal.total), commas(r.tfTotal.l1), pct1(r.tfTotal.l1, r.tfTotal.total))

	w("## Files\n\n")
	w("| File | One row per | Columns |\n| --- | --- | --- |\n")
	w("| [services.csv](services.csv) | service | `service,resources_total,resources_official,resources_ours_beyond,attributes_total,attributes_official,attributes_ours_beyond,attributes_uncovered,pct_official,pct_ours_beyond,pct_uncovered` |\n")
	w("| [resources.csv](resources.csv) | resource | `service,resource,attributes_total,official_kinds,attributes_official,ours_kinds,attributes_ours_beyond,attributes_uncovered,ours_from_upstream_pr,notes` |\n")
	w("| [attributes.csv](attributes.csv) | attribute | `service,resource,attribute,type,required,covered_by,official_path,ours_path` |\n")
	w("| `bars/<service>.svg`, `bars/_total.svg` | service, and all | stacked bars: official blue, ours beyond official green, uncovered light grey; under them the Terraform estimate in purple with its strict floor as a dark tick (see Terraform); `_total.svg` shows attributes, resources and Terraform |\n")
	w("| [priority.csv](priority.csv) | service | `service,tier,category,rationale,source`: the tier and category of each service, **hand-edited input** (see Tiers); a service not in it is tier 3, category `other` |\n")
	w("| [foundation.md](foundation.md) | | the ranked **foundation gap report**: the work queue for the kind agents (platform-foundation and security-adjacent resources: what ACK and we cover, what upstream has or is building, moto, size, proposed kinds) |\n")
	w("| [categories.csv](categories.csv), `bars/_categories.svg` | category | the same columns as `tiers.csv`, for `platform-foundation`, `security-adjacent`, `application`, `other` |\n")
	w("| [tiers.csv](tiers.csv), `bars/_tiers.svg` | tier | `tier,services,resources_total,resources_official,resources_ours_beyond,resources_uncovered,attributes_total,attributes_official,attributes_ours_beyond,attributes_uncovered,pct_attributes_official,pct_attributes_ours_beyond,pct_attributes_uncovered,pct_resources_official,pct_resources_ours_beyond,pct_resources_uncovered` |\n")
	w("| [inputs/terraform/terraform.csv](inputs/terraform/terraform.csv), [inputs/terraform/terraform-resources.csv](inputs/terraform/terraform-resources.csv) | service, and resource | the Terraform estimate, **pinned input** copied from the catalog repository (see Terraform); its columns are in the catalog's `docs/terraform/README.md` |\n")
	w("| [sources.yaml](sources.yaml) | | every pinned input: the schema zip, each ACK controller's release and commit, and the catalog commit of the Terraform estimate |\n\n")
	w("In `attributes.csv`, `covered_by` is `official` (an official ACK kind covers it and ours does not), `ours` (ours covers it and official does not), `both`, or `none`; `official_path` and `ours_path` are the CRD `spec` path that covers it (`;`-separated, with the kind in front when several kinds of that side cover the resource). In `services.csv` and `resources.csv`, `attributes_official` counts `official` and `both`, `attributes_ours_beyond` counts `ours` only, and the three percentages are of `attributes_total` (so each row adds to 100.0, give or take rounding). `resources_official` counts resources with an official kind; `resources_ours_beyond` counts resources with a kind of ours and none official. `notes` carries `official_unmapped=N` and `ours_unmapped=N` (spec paths of the CRDs that matched no CloudFormation property), the kind of ours that is a property of a larger resource, and `outside-denominator`.\n\n")

	w("## Definitions\n\n")
	w("- **service**: an AWS service, by its CloudFormation service name lower-cased (`rds`, `lambda`, `events` for EventBridge, `elasticloadbalancingv2` for ELBv2). A CloudFormation service is the second part of `AWS::<Service>::<Resource>`.\n")
	w("- **resource**: one CloudFormation resource type, written `rds/DBInstance` for `AWS::RDS::DBInstance`.\n")
	w("- **attribute**: a *writable* (input) property of a resource, as a dotted path: arrays as `[]`, maps as `{}`, so `Tags[].Key` and `SecurityGroupIds[]`. Only leaves count: an object with properties is not itself an attribute, but its properties are; an object with no declared properties (a free-form JSON value) is one attribute. A property is **read-only** if its pointer, or one above it, is in the schema's `readOnlyProperties`; read-only properties are excluded. `createOnlyProperties` are *not* excluded: they are writable at create. `writeOnlyProperties` (passwords) are writable and counted. `required` is true only if the property and every object above it are required. Where a schema defines a definition that contains itself (WAFv2 statements, Glue and Lex structures), the walk stops at the second occurrence and counts the cut point as one free-form attribute; that happened %s times across the schemas.\n", commas(m.cfnCut))
	w("- **official**: covered by ACK's own controllers (`aws-controllers-k8s/<service>-controller`) at the **latest release** of each. A service is covered when the controller's released CRDs (`helm/crds/` at the release commit) have a CRD for the resource. Controllers with no release are not official (listed below).\n")
	w("- **ours**: covered by a kind in this repository's CRDs (`config/crds/bases/`, at the commit being measured). A kind whose coverage is copied from an open upstream pull request has `ours_from_upstream_pr=true` (%s of the attributes ours adds beyond official come only from such kinds).\n", commas(t.oursBeyondPR))
	w("- **uncovered**: in the CloudFormation schemas, covered by neither.\n\n")

	w("## Tiers and categories\n\n")
	w("Services do not matter equally: `quicksight` alone has more attributes than all of tier 1 together, yet a platform team needs `organizations`, `iam`, VPC networking and `eks` first. So every service has a **category** and a **tier**, and the README shows coverage by both as well as in total.\n\n")
	w("**Categories** (decided 2026-11-09):\n\n")
	w("- **platform-foundation**: everything up to a managed Kubernetes cluster, which is table stakes for a platform team establishing a target: Organizations (accounts, OUs, SCPs and the other policy types, delegated administrators, organization features), Control Tower, IAM (roles, policies, boundaries, OIDC and SAML providers), IAM Identity Center and the Identity Store, Resource Access Manager, VPC networking and DNS (`ec2` for VPC, subnets, route tables, gateways, Transit Gateway, endpoints, security groups, NACLs and VPN; `route53`, `route53resolver`, `route53profiles`; `networkmanager`, `directconnect`), KMS, CloudTrail, EKS and ECR: `%s`.\n", strings.Join(sortedCategoryServices(r, catPlatform), "`, `"))
	w("- **security-adjacent**: what security teams need next to it: Config, GuardDuty, Security Hub, Macie, Inspector, Detective, Access Analyzer, Firewall Manager, WAF, Secrets Manager, ACM and private CAs, Audit Manager, Security Lake, Network Firewall: `%s`.\n", strings.Join(sortedCategoryServices(r, catSecurity), "`, `"))
	w("- **application**: application primitives (S3, SQS, SNS, Lambda, RDS, DynamoDB, ElastiCache, ECS and so on): the services some tracked Terraform module uses that are in neither category above (%d services; the list is `priority.csv`).\n", len(sortedCategoryServices(r, catApp)))
	w("- **other**: everything else in the CloudFormation schemas (%d services). A service missing from `priority.csv` is tier 3, category `other`.\n\n", len(sortedCategoryServices(r, catOther)))
	w("**Tiers**: tier 1 is the platform-foundation services; tier 2 is the security-adjacent services and the application services some tracked module uses; tier 3 is everything else. (Before 2026-11-09 tier 1 was the services of the ten most-downloaded terraform-aws-modules; the 2026-11-09 brief replaced that where the two conflict, so `s3`, `lambda`, `rds` and `logs` moved to tier 2. The module-usage ranking stays as each row's rationale.)\n\n")
	w("| Category | Services | Resources | ACK | Ours beyond | Attributes | ACK | Ours beyond | Terraform (estimate) |\n| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |\n")
	for _, t := range r.categoryRows() {
		w("| %s | %d | %s | %s%% | %s%% | %s | %s%% | %s%% | %s |\n", t.label, t.services, commas(t.resTotal), pct1(t.resOfficial, t.resTotal), pct1(t.resOursBeyond, t.resTotal), commas(t.attrTotal), pct1(t.attrOfficial, t.attrTotal), pct1(t.attrOursBeyond, t.attrTotal), tfCell(t.tf, true))
	}
	w("\n| Tier | Services | Resources | ACK | Ours beyond | Attributes | ACK | Ours beyond | Terraform (estimate) |\n| ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |\n")
	for _, t := range r.tierRows() {
		w("| %d | %d | %s | %s%% | %s%% | %s | %s%% | %s%% | %s |\n", t.tier, t.services, commas(t.resTotal), pct1(t.resOfficial, t.resTotal), pct1(t.resOursBeyond, t.resTotal), commas(t.attrTotal), pct1(t.attrOfficial, t.attrTotal), pct1(t.attrOursBeyond, t.attrTotal), tfCell(t.tf, true))
	}
	w("\n**The foundation gap report.** [foundation.md](foundation.md) ranks every resource of the platform-foundation and security-adjacent categories as a work queue for the kind agents: ACK coverage, ours, what is missing (whole resources first, then the attributes that matter), whether upstream has it or is building it (ACK controller releases, `generator.yaml` ignore lists, open pull requests and `community` issues, all read-only), how many of the 40 tracked terraform-aws-modules need it, whether moto 5.2.5 implements the API (we can only prove kinds against moto), a size estimate and the proposed kinds. Its numbers are regenerated; its research is `hack/coverage/foundation.yaml`.\n\n")
	w("**Where it comes from.** `priority.csv` is hand-edited input. The module-usage rationale came once, by hand, from the usage ranking in `catalog/docs/aws.md` (the High Five Labs catalog repository, commit `b6fdd5342346997fe855357eeee225afb7530e95`, file sha256 `8c2ab34d8e50130e19bfa0619ffc0c9800646d26e8bebac9de347a574a681533`, read 2026-11-09), which ranks the terraform-aws-modules by Terraform Registry downloads over the last year and lists what each top module and submodule creates. The categories and the tier-1 definition come from the brief of 2026-11-09. Services are the CloudFormation service names used everywhere else here. The generator **reads** the file and never rewrites it, so any tier or category can be overridden by editing a row; it rejects a tier outside 1 to 3, an unknown category, a duplicate, and a service that is not in the CloudFormation schemas (a typo guard).\n\n")
	w("**Limits.**\n\n")
	w("- Module usage is a proxy for what teams need, and it does not reach the foundation at all: none of the 40 tracked modules wraps Organizations, Identity Center, Control Tower, CloudTrail, Config, GuardDuty or Security Hub, so for those the brief, not the modules, ranks them. Downloads count module fetches, not teams, and only the terraform-aws-modules organisation's modules are tracked: a service nobody wraps in one of them is tier 3 or `other` however important it is to you.\n")
	w("- A category is a whole service, but a module (or a platform team) uses a few of its resources. `ec2` is platform-foundation for networking, and its other resources (it has %d; the modules use perhaps a dozen) ride along; so the category's coverage understates how well the *used* resources are covered. [foundation.md](foundation.md) ranks the networking resources of `ec2` ahead of the rest and lists every one.\n", m.cfnResourcesIn("ec2"))
	w("- Neither tiers nor categories weigh services within them, and `iam` (one module on every stack) counts the same as `route53profiles`.\n")
	w("- Coverage counts a resource that ACK or ours covers as fields of another kind (security group rules, route table routes, inline IAM policies) as uncovered, because the CloudFormation schema has a resource of its own for each; [foundation.md](foundation.md) marks those \"covered inline\" so they are not mistaken for gaps.\n")
	w("- The research behind [foundation.md](foundation.md) is a snapshot of 2026-11-09 and is not regenerated: re-read upstream before starting an item.\n\n")

	w("## Method\n\n")
	w("1. **Denominator.** The CloudFormation resource-schema zip for us-east-1 (every `AWS::*` resource type: %s resources in %d services, %s writable attributes after removing %s read-only leaves). `Alexa::ASK::Skill` is dropped. Resources with no writable property are kept (they count as resources, not attributes).\n", commas(len(m.cfn)), len(m.services), commas(t.attrTotal), commas(m.cfnReadOnly))
	w("2. **Official.** For every ACK controller repository with a published GitHub release, the latest release's tag is resolved to a commit, and every CRD under `helm/crds/` (except ACK's own `services.k8s.aws` kinds, `FieldExport` and `IAMRoleSelector`) is read. The CRD's `spec` is walked the same way as a CloudFormation schema: leaves become dotted paths (ACK's `*Ref` reference fields are skipped, each stands for an ID field already counted; a `{name, namespace, key}` secret reference is one string).\n")
	w("3. **Ours.** The same walk over this repository's `config/crds/bases/*.yaml`.\n")
	w("4. **Which resource a kind is.** A kind is the CloudFormation resource of the same name in the same service (case and punctuation ignored: `VPCLink` is `VpcLink`). The service ids that differ are in `hack/coverage/mappings.yaml` (`acm` is `certificatemanager`, `eventbridge` is `events`, `sfn` is `stepfunctions`, `kafka` is `msk`, ...), as are the kinds whose name differs (`ElasticIPAddress` is `EIP`, `Policy` is `ManagedPolicy`) and the kinds with no CloudFormation resource. A kind of ours that is a *property* of a larger CloudFormation resource is mapped to that resource and its properties: `applicationautoscaling` `ScheduledAction` to `ScalableTarget.ScheduledActions[]`, `LoginProfile` to `User.LoginProfile`, `UserGroupMembership` to `User.Groups[]`, `RolePolicyAttachment` to `Role.ManagedPolicyArns[]`, `DBProxyTarget` to `DBProxyTargetGroup`, `DBRoleAssociation` to `DBCluster` and `DBInstance` `.AssociatedRoles[]`; the resource row says so in `notes`.\n")
	w("5. **Which attribute a spec field is.** Tiers, tightest first; a looser tier sees only what the tighter ones left, and from `primary-name` down a match is accepted only when each side has exactly one candidate.\n\n")
	w("| Tier | Rule | Official | Ours |\n| --- | --- | ---: | ---: |\n")
	tiers := []struct{ name, rule string }{
		{"exact", "the same path, names compared lower-cased without punctuation, `[]` and `{}` kept (`DBInstanceClass` and `dbInstanceClass`; ACK's `{quantity, items[]}` wrappers count as the list)"},
		{"alias", "a path-prefix rename written by hand in `mappings.yaml` (`ingressRules[]` is `SecurityGroupIngress[]`)"},
		{"tags-map", "CloudFormation's `Tags[].Key` and `Tags[].Value` against ACK's `tags{}` map"},
		{"free-form", "the CRD takes a free-form value (`x-kubernetes-preserve-unknown-fields`) above the CloudFormation path, so it covers everything under it"},
		{"structured", "CloudFormation takes a free-form object where the CRD has a map or declared structure under the same name (WAFv2 `Method` and `{}`, DynamoDB `KeySchema`)"},
		{"primary-name", "ACK's `name` field against the one writable primary-identifier property (`ClusterName`)"},
		{"name-suffix", "same parent, the last name of one ends with the other (`description` and `GroupDescription`, `policy` and `KeyPolicy`), unique both ways"},
		{"name-variant", "same path after canonicalizing each name: plurals, `identifier` and `id`, `Ids` and `s`, `enableFoo` and `fooEnabled`, `*Tags`, `tagKey` and `key`; unique both ways"},
		{"tail-4", "the last four names agree (a wrapper above them was renamed or dropped) and the list depth is the same, unique both ways"},
		{"tail-3", "the same, last three names"},
		{"tail-2", "the same, last two names"},
		{"leaf-name", "the same last name, type class and list depth, unique both ways among what is left"},
	}
	for _, x := range tiers {
		w("| `%s` | %s | %s | %s |\n", x.name, x.rule, commas(m.howOfficial[x.name]), commas(m.howOurs[x.name]))
	}
	w("\nThe tiers run in this order in the code: exact and alias, tags-map, free-form, structured, primary-name, name-suffix, name-variant, tail-4, tail-3, tail-2, leaf-name. The first two are by design exact; the rest are heuristics, and `leaf-name` is the loosest.\n\n")
	w("To see any resource's matching, with the tier that matched each attribute and the CRD paths that matched nothing:\n\n```sh\nhack/coverage/run.sh -explain rds/DBInstance\n```\n\n")

	// Terraform.
	tf := src.Terraform
	w("## Terraform\n\n")
	w("Every bar carries a thin **purple** bar under it: the share of the same attributes (the CloudFormation denominator) that a writable attribute of a mapped resource of the Terraform `aws` provider matches, so a reader can compare ACK and ours with what a team migrating from Terraform has today. The bar is the lenient match (`pct_terraform_l2`), the dark tick on it the strict one (`pct_terraform_l1`), which is its floor. It is drawn beside official and ours, not stacked with them: they overlap.\n\n")
	w("**It is an estimate, not a measurement.** The catalog repository maps each Terraform resource to CloudFormation resources and matches attribute names by rule; it under-counts where the provider renames or restructures a field and over-counts where two fields share a name. Its method and error are [\"Method and error\" in `docs/terraform-leverage.md`](%s) of the catalog repository. Nothing here recomputes it: the generator reads the numbers as they are.\n\n", tfMethodLink(src))
	w("**Where it comes from.** `%s` (private), commit `%s` (%s), copied %s: ", tf.Repo, tf.Commit, tf.CommitDate, tf.Fetched)
	for i, f := range tf.Files {
		if i > 0 {
			w("; ")
		}
		w("`%s` as [`%s`](%s), sha256 `%s`", f.From, strings.TrimPrefix(f.Path, "docs/coverage/"), strings.TrimPrefix(f.Path, "docs/coverage/"), f.SHA256)
	}
	w(". The copies are committed, as the catalog repository is private, and the generator refuses a copy whose checksum differs from `sources.yaml`. Only the `%s` provider's rows are read: `terraform.csv` gives each service's bar and table cell; the totals, categories and tiers are sums of its `attributes_terraform_l1`, `attributes_terraform_l2` and `attributes_total` over every row (%d rows, %s attributes; a service the estimate has and the dashboard no longer has still counts in the total), grouped by this dashboard's category and tier. `terraform-resources.csv` lists, resource by resource, the Terraform resources each match relied on. The shared CSVs here (`services.csv`, `categories.csv`, `tiers.csv`, ...) carry no Terraform column.\n\n", tf.Provider, len(r.tfRows), commas(r.tfTotal.total))
	w("The estimate was made against this dashboard's denominator at the time, so its `attributes_total` can drift from `services.csv` as the CloudFormation pin moves; move the Terraform pin after the catalog reruns its analysis:\n\n```sh\nhack/coverage/run.sh -terraform-pin <catalog commit>   # reads $CATALOG_DIR (default ../catalog), copies the two files, rewrites sources.yaml, regenerates\n```\n\n")

	// Pinned sources.
	w("## Pinned sources\n\n")
	cf := src.CloudFormation
	w("**CloudFormation resource schemas.** `%s` (region %s), fetched %s (`Last-Modified: %s`), %s bytes, sha256 `%s`. AWS rebuilds the file at that URL every hour, so it cannot reproduce an old pin; the pinned copy is committed as [`%s`](inputs/CloudformationSchema.zip) and the generator refuses a copy whose checksum differs from this one.\n\n", cf.URL, cf.Region, cf.Fetched, cf.LastModified, commas(int(cf.Bytes)), cf.SHA256, strings.TrimPrefix(cf.File, "docs/coverage/"))
	w("**ACK controllers.** %s, resolved %s: the latest GitHub release of every `*-controller` repository that has one and has CRDs. Source: `https://raw.githubusercontent.com/%s/<repo>/<commit>/helm/crds/<file>`; the commit is the release tag resolved at the time (tags can move; commits cannot). The same table, with each CRD's path, is [sources.yaml](sources.yaml).\n\n", src.ACK.Org, src.ACK.Resolved, src.ACK.Org)
	w("| Controller | Release | Commit | CRDs |\n| --- | --- | --- | ---: |\n")
	for _, c := range src.ACK.Controllers {
		note := ""
		if c.Archived {
			note = " (archived)"
		}
		w("| `%s`%s | `%s` | `%s` | %d |\n", c.Name, note, c.Release, c.Commit[:12], len(c.CRDs))
	}
	w("\nNo release (or none with CRDs), so counted as covering nothing officially: %s.\n\n", codeList(trimController(src.ACK.NoRelease)))
	w("This repository's own pins (`UPSTREAM.md`) cover only a few of these controllers; the dashboard reads all of them. Our kinds are read from `config/crds/bases/` of the commit being measured; `git log -1 -- config/crds` dates it.\n\n")

	// Known error.
	w("## Known error and caveats\n\n")
	var bound, offMatched, offUnmapped, offPaths int
	for k, cvs := range m.official {
		for _, cv := range cvs {
			u := len(m.cfn[k].Attrs) - len(cv.Match)
			v := len(cv.Unmapped)
			if v < u {
				u = v
			}
			bound += u
			offMatched += len(cv.Match)
			offUnmapped += len(cv.Unmapped)
			offPaths += len(cv.CRD.Attrs)
		}
	}
	var ourMatched, ourUnmapped int
	for _, cvs := range m.ours {
		for _, cv := range cvs {
			ourMatched += len(cv.Match)
			ourUnmapped += len(cv.Unmapped)
		}
	}
	w("- **Unmapped.** Of the %s spec paths in the %d official CRDs mapped to a CloudFormation resource, %s matched no CloudFormation property (**unmapped = %s**). Some are ACK-only fields (`clientRequestToken`, cross-resource helpers, fields ACK takes from the SDK that CloudFormation lacks); the rest are renames the matcher missed. Ours: %s of %s spec paths unmapped. Both are listed per resource as `official_unmapped` and `ours_unmapped` in `resources.csv` and per attribute by `-explain`.\n", commas(offPaths), len(m.official), commas(offUnmapped), commas(offUnmapped), commas(ourUnmapped), commas(ourUnmapped+ourMatched))
	w("- **Upper bound on the understatement.** Where ACK covers a property under a name the matcher cannot pair, official coverage is under-counted. A resource's misses cannot exceed the smaller of its unmatched CloudFormation attributes and its unmapped spec paths; summed over every official kind that is **%s attributes (%s%% of the denominator, %s%% of what is counted as official)**. The real figure is far lower, because most unmapped paths have no CloudFormation counterpart: the spot checks below found about 2%% of covered attributes missed.\n", commas(bound), pct1(bound, t.attrTotal), pct1(bound, t.attrOfficial))
	w("- **No false credit from the denominator's shape.** An attribute is a leaf, so a resource with a very deep schema weighs more than a flat one. The largest services by attributes are %s. Percentages by *resource* are in `services.csv` too (`resources_official / resources_total`). A resource with ACK coverage of one field of a hundred still counts as one official resource.\n", topServices(r))
	w("- **CloudFormation is not the API.** The denominator is CloudFormation's view of each service. Operations CloudFormation does not model (jobs, executions, one-shot actions, data-plane calls) are not in it, and neither is anything an ACK kind covers that CloudFormation lacks; that is why some kinds are outside it (below). A service ACK covers that CloudFormation has no resource for is not penalised, but it is not credited either.\n")
	w("- **Official is the latest *release*.** ACK `main` is ahead of its releases for many controllers; that work is not counted. Controllers with no release count as nothing.\n")
	w("- **Recursion.** %s recursive definitions were cut (see Definitions); ACK cuts at a different depth, so `wafv2` and the like are matched on the attributes both sides spell out.\n", commas(m.cfnCut))
	w("- **Polymorphic schemas.** `oneOf`/`anyOf`/`allOf` members are merged: an attribute is counted once if any branch declares it.\n")
	w("- **Same attribute, different shape.** Where ACK takes a JSON document as a string and CloudFormation as a nested object (policies), the string is credited against the document attribute when the names pair; a nested CloudFormation object that ACK takes as one string is credited only through a `free-form` or alias entry.\n")
	w("- **Ours counts a kind once it is in `config/crds/bases/`**, whether or not it is released or deployed; pull-request copies are flagged. Ours is counted as covering an attribute when its CRD has a field for it; it does not measure how well the controller behaves (see `docs/plan.md`).\n\n")

	// Outside the denominator.
	w("## Outside the denominator\n\n")
	w("Kinds with no CloudFormation resource get a row in `resources.csv` with `notes=outside-denominator` and zero attributes, and are in none of the percentages.\n\n")
	var offOut, ourOut []string
	for _, cv := range m.outsideOfficial {
		offOut = append(offOut, cv.Svc+"/"+cv.Kind)
	}
	for _, cv := range m.outsideOurs {
		ourOut = append(ourOut, cv.Svc+"/"+cv.Kind)
	}
	sort.Strings(offOut)
	sort.Strings(ourOut)
	w("- **Official (%d):** %s.\n", len(offOut), codeList(offOut))
	if len(ourOut) == 0 {
		w("- **Ours (0):** none. Six of our kinds are not CloudFormation resources of their own but properties of a larger one (point 4 of the Method); they are measured as those properties.\n")
	} else {
		w("- **Ours (%d):** %s.\n", len(ourOut), codeList(ourOut))
	}
	w("\n**Services missing from the CloudFormation schemas.** ")
	if len(m.ackServicesAbsent) == 0 {
		w("None.\n\n")
	} else {
		w("%s. The plan was to fall back to the Create* input shapes in botocore or aws-sdk-go-v2's `api-models` for such a service; that fallback is not built, because only %d service (a few kinds, all brand new) needs it. Its kinds are listed above as outside the denominator rather than being measured against a model, so they are neither credited nor penalised.\n\n", codeList(m.ackServicesAbsent), len(m.ackServicesAbsent))
	}

	w("## Spot checks\n\n")
	b.WriteString(strings.TrimSpace(spotChecks))
	w("\n\n")

	w("## Regenerating\n\n")
	w("```sh\nhack/coverage/run.sh               # regenerate everything under docs/coverage/ and the README's Coverage section\nhack/coverage/run.sh --check       # fail if the committed outputs differ from a regeneration from the pinned inputs\nhack/coverage/run.sh --update-pins # move the pins to the latest ACK releases and the current CloudFormation zip, then regenerate (the Terraform pin is kept)\nhack/coverage/run.sh -terraform-pin <commit> # move the Terraform estimate to that catalog commit, then regenerate\nhack/coverage/run.sh -explain s3/Bucket\ntask coverage                      # the first; `task coverage:check` is the second\n```\n\n")
	w("The generator is Go (`hack/coverage/`, run from the root module; `go test ./hack/coverage` has its unit tests). Regeneration reads only the committed zip, the committed Terraform estimate (`inputs/terraform/`), `sources.yaml`, `priority.csv`, `hack/coverage/foundation.yaml`, `hack/coverage/module-usage.csv`, `hack/coverage/mappings.yaml` and `config/crds/bases/`, plus the pinned ACK CRDs, which it downloads from `raw.githubusercontent.com` at the pinned commits into the git-ignored `.cache/coverage/`. Outputs carry no timestamps; the only dates are the pins' own. `--update-pins` needs the `gh` CLI (read-only calls) and changes the committed zip; review the diff of `sources.yaml` before committing it.\n\n")
	w("To teach the matcher a rename, add a line to `attributes:` (an official kind) or `oursAttributes:` in `mappings.yaml`, a CRD path prefix on the left and the CloudFormation path prefix on the right, then regenerate and read `-explain` for that resource.\n")
	return []byte(b.String())
}

func codeList(l []string) string {
	if len(l) == 0 {
		return "none"
	}
	out := make([]string, len(l))
	for i, s := range l {
		out[i] = "`" + s + "`"
	}
	return strings.Join(out, ", ")
}

func trimController(l []string) []string {
	out := make([]string, len(l))
	for i, s := range l {
		out[i] = strings.TrimSuffix(s, "-controller")
	}
	return out
}

func topServices(r *results) string {
	s := append([]svcRow(nil), r.svcs...)
	sort.SliceStable(s, func(i, j int) bool { return s[i].attrTotal > s[j].attrTotal })
	var out []string
	for _, x := range s[:5] {
		out = append(out, fmt.Sprintf("`%s` (%s, %s%% of the total)", x.service, commas(x.attrTotal), pct1(x.attrTotal, r.total.attrTotal)))
	}
	return strings.Join(out, ", ")
}
